using System;using System.IO;using System.Linq;using System.Collections;using UnityEditor;using UnityEngine;using UnityEngine.UI;using Scripts.Skills;
[InitializeOnLoad]public static class BattleRefreshValidation{
const string O=BattleRefreshAuthoring.Out;static bool running;
static BattleRefreshValidation(){EditorApplication.update+=()=>{if(EditorApplication.isCompiling||EditorApplication.isUpdating)return;if(!EditorApplication.isPlayingOrWillChangePlaymode&&File.Exists(O+"validate.request")){File.Delete(O+"validate.request");File.WriteAllText(O+"validation.txt","");UnityEditor.SceneManagement.EditorSceneManager.OpenScene(EditorBuildSettings.scenes.First(s=>s.enabled).path);SessionState.SetBool("BR_QA",true);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",true);EditorApplication.isPlaying=true;}if(EditorApplication.isPlaying&&SessionState.GetBool("BR_QA",false)&&!running&&GameManager.single&&GameplayCanvas.single){running=true;GameManager.single.StartCoroutine(Run());}};EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode){running=false;SessionState.SetBool("BR_QA",false);SessionState.SetBool("MONSTER_QA_DISABLE_SAVE",false);Time.timeScale=1;}};}
static void Check(bool b,string s)=>File.AppendAllText(O+"validation.txt",(b?"PASS ":"FAIL ")+s+"\n");
static void Shot(string name){var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(O+name+".png",t.EncodeToPNG());UnityEngine.Object.Destroy(t);}
static IEnumerator Run(){var intro=UnityEngine.Object.FindAnyObjectByType<CursedBookIntro>();while(intro&&intro.gameObject.activeSelf)yield return null;yield return new WaitForSecondsRealtime(1);var gc=GameplayCanvas.single;var gm=GameManager.single;gc.GetComponent<StorybookDailyReward>().enabled=false;gc.dailyCherriesPop.SetActive(false);gc.CancelInvoke("TryShowingXpBoosterNotification");gc.xpBoosterNotification.SetActive(false);TutorialManager.single.automatic=false;TutorialManager.single.view.Hide();foreach(var d in UnityEngine.Object.FindObjectsByType<DebugMenu>(FindObjectsInactive.Include,FindObjectsSortMode.None))d.enabled=false;var dev=UnityEngine.Object.FindAnyObjectByType<DeveloperOverlayUI>();if(dev)dev.gameObject.SetActive(false);
var sc=SkillsController.Instance;sc.ResetSkills();sc.regenLevel=1;sc.angelOnMyShoulderLevel=1;sc.devilOnMyShoulderLevel=1;sc.lightningDemiGodlevel=1;sc.cindrelLevel=0;gm.playerLevel=1;gm.rebirthLevel=0;gm.xpNow=0;gm.xpMax=9999;gm.isBoostedXPActive=false;
gm.lastBattleKey="Black Forest Mushroom Test";
Router.single.LastBattle();yield return new WaitForSecondsRealtime(1.1f);Player.single.StopAllCoroutines();Player.single.ab.currentStat.dmg=0;yield return new WaitForSecondsRealtime(.8f);Time.timeScale=0;foreach(var enemy in UnityEngine.Object.FindObjectsByType<Enemy>(FindObjectsSortMode.None)){if(enemy.ab.enemyLifebar){enemy.ab.enemyLifebar.gameObject.SetActive(true);enemy.ab.enemyLifebar.hpText.text="1 / 3";enemy.ab.enemyLifebar.hpMeter.SetValue(null,1f/3,false);}}yield return new WaitForSecondsRealtime(4);var hud=gc.battleHud;var status=hud.statusDetails;hud.SetHealth(12,14,false);hud.SetExperience(1,0,999);hud.SetWave(1,3);Check(hud.isActiveAndEnabled&&status,"Authored battle HUD route");
foreach(var sz in new[]{new Vector2Int(1080,1920),new Vector2Int(768,1024),new Vector2Int(720,1440)}){StorybookEquipmentValidation.Resolution(sz.x,sz.y);yield return new WaitForSecondsRealtime(.4f);hud.SetHealth(12,14,false);hud.SetExperience(1,0,999);Check(Mathf.Abs(hud.hpFill.rectTransform.rect.width-hud.xpFill.rectTransform.rect.width)<1,"Equal length HP XP "+sz);Check(status.skillSlots.Count(n=>n.activeSelf)==4,"Only learned status skills visible "+sz);Check(status.skillSlots.All(n=>!n.GetComponent<Button>())&&status.GetComponentsInChildren<Graphic>().Where(g=>g.transform.IsChildOf(status.skillSlots[0].transform)).All(g=>!g.raycastTarget),"Status icons do not intercept input "+sz);yield return new WaitForEndOfFrame();Shot("battle-"+sz.x+"x"+sz.y);
gm.IncXp(25);yield return new WaitForSecondsRealtime(.22f);float y=status.notification.position.y;Check(status.notificationText.text.Contains("25")&&status.notificationGroup.alpha>.5f,"Actual XP amount above portrait "+sz);yield return new WaitForEndOfFrame();Shot("xp-"+sz.x+"x"+sz.y);yield return new WaitForSecondsRealtime(.35f);Check(status.notification.position.y>y,"XP rises "+sz);yield return new WaitForSecondsRealtime(1.3f);Check(status.notificationGroup.alpha==0,"XP fades "+sz);
gm.playerLevel=2;gc.PlayLevelUp();yield return new WaitForSecondsRealtime(.24f);Check(status.notificationText.text.Contains("等级提升")&&!gc.levelUpUI.Presenting,"Level up uses portrait feedback "+sz);yield return new WaitForEndOfFrame();Shot("level-"+sz.x+"x"+sz.y);yield return new WaitForSecondsRealtime(2.5f);gm.playerLevel=1;}
Check(status.cooldownMasks.All(i=>i.fillMethod==Image.FillMethod.Radial360&&i.fillOrigin==(int)Image.Origin360.Top&&!i.fillClockwise),"Radial remainder clears clockwise from twelve");Check(status.cooldownMasks[0].fillAmount>=0&&status.cooldownMasks[0].fillAmount<=1,"Cooldown follows actual player timer");
Time.timeScale=1;yield return Router.single.GoToCampFromBattle();yield return new WaitForSecondsRealtime(1);Check(gc.homeUI.gameObject.activeInHierarchy&&!hud.gameObject.activeInHierarchy&&status.notificationGroup.alpha==0,"Return restores home and clears portrait feedback");
Router.single.LastBattle();yield return new WaitForSecondsRealtime(1.1f);Router.single.newChest=new Chest{crystalsMin=10,crystalsMax=20};yield return Router.single.GoToVictory();Check(gc.victoryPanel.activeInHierarchy&&!hud.gameObject.activeInHierarchy,"Victory hides HUD and opens results");yield return Router.single.GoToCampFromBattle();yield return new WaitForSecondsRealtime(1);
Router.single.LastBattle();yield return new WaitForSecondsRealtime(1.1f);yield return Router.single.GoToDefeat();Check(gc.defeatPanel.activeInHierarchy&&!hud.gameObject.activeInHierarchy,"Defeat hides HUD and opens results");yield return Router.single.GoToCampFromBattle();yield return new WaitForSecondsRealtime(1);Check(gc.homeUI.gameObject.activeInHierarchy,"Results return to camp");
File.AppendAllText(O+"validation.txt","DONE\n");EditorApplication.isPlaying=false;
}}
